From 554e4bfeddde8249356673e9366c96e291afec5e Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 16:49:12 +0100
Subject: [PATCH] applets/digital-clock: Follow the 12/24-hour setting in Copy
 to Clipboard

The Copy to Clipboard menu used the locale's time formats as they are, so
it offered AM/PM times while the clock was set to 24-hour time, and the
other way round. Pass the setting to the menu and switch both formats.

BUG: 452888
---
 applets/digital-clock/DigitalClock.qml        |  1 +
 .../digital-clock/plugin/clipboardmenu.cpp    | 89 +++++++++++++++++--
 applets/digital-clock/plugin/clipboardmenu.h  |  7 ++
 3 files changed, 89 insertions(+), 8 deletions(-)

diff --git a/applets/digital-clock/DigitalClock.qml b/applets/digital-clock/DigitalClock.qml
index 8c918109d0..4856acfe22 100644
--- a/applets/digital-clock/DigitalClock.qml
+++ b/applets/digital-clock/DigitalClock.qml
@@ -93,6 +93,7 @@ MouseArea {
         function onContextualActionsAboutToShow() {
             ClipboardMenu.secondsIncluded = (Plasmoid.configuration.showSeconds === 2);
             ClipboardMenu.timezone = clock.timeZone;
+            ClipboardMenu.use24hFormat = Plasmoid.configuration.use24hFormat;
         }
     }

diff --git a/applets/digital-clock/plugin/clipboardmenu.cpp b/applets/digital-clock/plugin/clipboardmenu.cpp
index 8e2708252f..bb4293ddc4 100644
--- a/applets/digital-clock/plugin/clipboardmenu.cpp
+++ b/applets/digital-clock/plugin/clipboardmenu.cpp
@@ -12,6 +12,65 @@
 #include <QMenu>
 #include <QRegularExpression>

+namespace
+{
+// Switches a locale time format to the 12 or 24-hour clock the widget is set to
+QString withHourCycle(const QString &format, Qt::CheckState use24hFormat)
+{
+    static const QRegularExpression fields(QStringLiteral("'[^']*'|\\s*[Aa][Pp]?\\s*|h+|H+|m+|s+|t+"), QRegularExpression::UseUnicodePropertiesOption);
+    const auto isAmPm = [](const QString &field) {
+        return field.trimmed().startsWith(QLatin1Char('A'), Qt::CaseInsensitive);
+    };
+
+    bool uses12h = false;
+    bool timeSeen = false;
+    // AM/PM goes before the time zone that follows the time, or at the end
+    qsizetype amPmAt = format.size();
+    for (const QRegularExpressionMatch &match : fields.globalMatch(format)) {
+        const QString field = match.captured();
+        if (isAmPm(field)) {
+            uses12h = true;
+        } else if (field.startsWith(QLatin1Char('t'))) {
+            if (timeSeen && amPmAt == format.size()) {
+                amPmAt = match.capturedStart();
+            }
+        } else if (!field.startsWith(QLatin1Char('\''))) {
+            timeSeen = true;
+        }
+    }
+    const bool use12h = use24hFormat == Qt::Unchecked || (use24hFormat == Qt::PartiallyChecked && uses12h);
+    if (use12h == uses12h) {
+        return format;
+    }
+
+    QString withAmPm = format;
+    if (use12h) {
+        while (amPmAt > 0 && format[amPmAt - 1].isSpace()) {
+            --amPmAt;
+        }
+        withAmPm.insert(amPmAt, QStringLiteral(" AP"));
+    }
+
+    QString result;
+    qsizetype last = 0;
+    for (const QRegularExpressionMatch &match : fields.globalMatch(withAmPm)) {
+        result += QStringView(withAmPm).sliced(last, match.capturedStart() - last);
+        last = match.capturedEnd();
+        const QString field = match.captured();
+        if (field.startsWith(QLatin1Char('h'), Qt::CaseInsensitive)) {
+            // Like the clock itself, zero-pad forced 24-hour times
+            result += use12h ? QStringLiteral("h") : QStringLiteral("HH");
+        } else if (isAmPm(field) && !use12h) {
+            result += QLatin1Char(' ');
+        } else {
+            result += field;
+        }
+    }
+    result += QStringView(withAmPm).sliced(last);
+    return result.trimmed();
+}
+}
+
 ClipboardMenu::ClipboardMenu(QObject *parent)
     : QObject(parent)
 {
@@ -45,6 +104,19 @@ void ClipboardMenu::setSecondsIncluded(bool secondsIncluded)
     }
 }

+int ClipboardMenu::use24hFormat() const
+{
+    return m_use24hFormat;
+}
+
+void ClipboardMenu::setUse24hFormat(int use24hFormat)
+{
+    if (m_use24hFormat != use24hFormat) {
+        m_use24hFormat = use24hFormat;
+        Q_EMIT use24hFormatChanged();
+    }
+}
+
 void ClipboardMenu::setupMenu(QAction *action)
 {
     auto *menu = new QMenu;
@@ -62,19 +134,22 @@ void ClipboardMenu::setupMenu(QAction *action)

         const QDate date = currentDateTime.date();
         const QTime time = currentDateTime.time();
-        const QRegularExpression rx(QStringLiteral("[^0-9:]"));
+        const QLocale locale = QLocale::system();
+        const auto use24hFormat = Qt::CheckState(m_use24hFormat);
+        const QString shortTime = locale.toString(time, withHourCycle(locale.timeFormat(QLocale::ShortFormat), use24hFormat));
+        const QString longTime = locale.toString(time, withHourCycle(locale.timeFormat(QLocale::LongFormat), use24hFormat));
         const QChar spaceCharacter = QLatin1Char(' ');
         QString timeString;
         QAction *menuOption;

         // e.g 12:30 PM or 12:30:01 PM
-        timeString = m_secondsIncluded ? QLocale::system().toString(time, QLocale::LongFormat) : QLocale::system().toString(time, QLocale::ShortFormat);
+        timeString = m_secondsIncluded ? longTime : shortTime;
         menuOption = menu->addAction(timeString);
         menuOption->setData(timeString);

         // the same as the option above but shows the opposite of the "show seconds" setting
         // e.g if "show seconds" is enabled it will show the time without seconds and vice-versa
-        timeString = m_secondsIncluded ? QLocale::system().toString(time, QLocale::ShortFormat) : QLocale::system().toString(time, QLocale::LongFormat);
+        timeString = m_secondsIncluded ? shortTime : longTime;
         menuOption = menu->addAction(timeString);
         menuOption->setData(timeString);

@@ -89,9 +164,8 @@ void ClipboardMenu::setupMenu(QAction *action)
         menuOption->setData(timeString);

         // e.g Thursday, April 28, 2022 12:30 PM or Thursday, April 28, 2022 12:30:01 PM -03
-        timeString = m_secondsIncluded
-            ? QLocale::system().toString(date, QLocale::LongFormat) + spaceCharacter + QLocale::system().toString(time, QLocale::LongFormat)
-            : QLocale::system().toString(date, QLocale::LongFormat) + spaceCharacter + QLocale::system().toString(time, QLocale::ShortFormat);
+        timeString = m_secondsIncluded ? QLocale::system().toString(date, QLocale::LongFormat) + spaceCharacter + longTime
+                                       : QLocale::system().toString(date, QLocale::LongFormat) + spaceCharacter + shortTime;
         menuOption = menu->addAction(timeString);
         menuOption->setData(timeString);

@@ -101,8 +175,7 @@ void ClipboardMenu::setupMenu(QAction *action)
         menuOption->setData(timeString);

         // e.g 2022-04-28 12:30 PM or 2022-04-28 12:30:01 PM -03
-        timeString = m_secondsIncluded ? date.toString(Qt::ISODate) + spaceCharacter + QLocale::system().toString(time, QLocale::LongFormat)
-                                       : date.toString(Qt::ISODate) + spaceCharacter + QLocale::system().toString(time, QLocale::ShortFormat);
+        timeString = m_secondsIncluded ? date.toString(Qt::ISODate) + spaceCharacter + longTime : date.toString(Qt::ISODate) + spaceCharacter + shortTime;
         menuOption = menu->addAction(timeString);
         menuOption->setData(timeString);

diff --git a/applets/digital-clock/plugin/clipboardmenu.h b/applets/digital-clock/plugin/clipboardmenu.h
index 8c33a0c0c4..b8addfc76b 100644
--- a/applets/digital-clock/plugin/clipboardmenu.h
+++ b/applets/digital-clock/plugin/clipboardmenu.h
@@ -20,6 +20,8 @@ class ClipboardMenu : public QObject
     // Holds the IANA timezone ID (e.g. "Europe/London")
     Q_PROPERTY(QByteArray timezone READ timezone WRITE setTimezone NOTIFY timezoneChanged)
     Q_PROPERTY(bool secondsIncluded READ secondsIncluded WRITE setSecondsIncluded NOTIFY secondsIncludedChanged)
+    // The widget's 12/24-hour setting as a Qt::CheckState, PartiallyChecked follows the locale
+    Q_PROPERTY(int use24hFormat READ use24hFormat WRITE setUse24hFormat NOTIFY use24hFormatChanged)

 public:
     explicit ClipboardMenu(QObject *parent = nullptr);
@@ -31,13 +33,18 @@ public:
     bool secondsIncluded() const;
     void setSecondsIncluded(bool secondsIncluded);

+    int use24hFormat() const;
+    void setUse24hFormat(int use24hFormat);
+
     Q_INVOKABLE void setupMenu(QAction *action);

 Q_SIGNALS:
     void timezoneChanged();
     void secondsIncludedChanged();
+    void use24hFormatChanged();

 private:
     QByteArray m_timezone;
     bool m_secondsIncluded = false;
+    int m_use24hFormat = Qt::PartiallyChecked;
 };
